using System.Text;
using Microsoft.CodeAnalysis.CSharp;

namespace Acta.Generators;

/// <summary>
/// Shared text helpers for the Acta source generators. Kept intentionally small: only what is
/// genuinely duplicated across the schema, projection, code, and job-manifest generators.
/// </summary>
internal static class GeneratorText
{
    /// <summary>
    /// Emit the two-line header every generated file shares: the <c>&lt;auto-generated/&gt;</c>
    /// marker (skips style analyzers / formatters) and <c>#nullable enable</c> (so generated code
    /// participates in NRT without inheriting the consumer's file-level pragma).
    /// </summary>
    public static void AutoGeneratedHeader(StringBuilder sb)
    {
        sb.AppendLine("// <auto-generated/>");
        sb.AppendLine("#nullable enable");
    }

    /// <summary>
    /// A declared name as generated source must spell it: a keyword, or a contextual keyword such as <c>await</c> that
    /// an async body would read as one, takes the verbatim <c>@</c>, which any identifier accepts.
    /// </summary>
    public static string EscapeIdentifier(string name) =>
        SyntaxFacts.GetKeywordKind(name) == SyntaxKind.None && SyntaxFacts.GetContextualKeywordKind(name) == SyntaxKind.None
            ? name
            : "@" + name;
}
